<script setup>
import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import api from '../api'
const router=useRouter(),loading=ref(false),registering=ref(false);const form=reactive({username:'',password:'',realName:'',phone:'',role:''});const mainlandMobile=/^1[3-9]\d{9}$/
async function submit(){if(registering.value&&!form.role){ElMessage.warning('请选择账号身份');return}if(registering.value){form.phone=form.phone.trim();if(form.phone&&!mainlandMobile.test(form.phone)){ElMessage.warning('请输入正确的11位中国大陆手机号');return}}loading.value=true;try{if(registering.value){await api.post('/auth/register',form);ElMessage.success('注册成功，请登录');registering.value=false}else{const {data}=await api.post('/auth/login',form);localStorage.setItem('heritage_token',data.data.token);localStorage.setItem('heritage_user',JSON.stringify(data.data.user));await router.push('/')}}catch{/* 请求错误已由统一拦截器提示 */}finally{loading.value=false}}
</script>
<template><div class="login"><section><div class="brand">非遗有迹 · 匠心永存</div><h1>民间非遗手工艺人<br>档案管理系统</h1><p>规范记录非遗艺人、技艺传承、作品成果与审核归档全过程。</p></section><el-card class="login-card"><h2>{{registering?'用户注册':'欢迎登录'}}</h2><el-form label-position="top" @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="form.username" maxlength="50" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" maxlength="100" autocomplete="current-password" show-password/></el-form-item><template v-if="registering"><el-form-item label="账号身份"><el-radio-group v-model="form.role" class="role-picker"><el-radio-button value="ARTISAN">非遗艺人</el-radio-button><el-radio-button value="VIEWER">普通用户</el-radio-button></el-radio-group></el-form-item><el-form-item label="真实姓名"><el-input v-model="form.realName" maxlength="50"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" type="tel" maxlength="11" inputmode="numeric" autocomplete="tel" placeholder="11位中国大陆手机号"/></el-form-item></template><el-button type="primary" native-type="submit" :loading="loading" style="width:100%">{{registering?'立即注册':'登录系统'}}</el-button><el-button link style="width:100%;margin:12px 0 0" @click="registering=!registering">{{registering?'已有账号，返回登录':'没有账号？立即注册'}}</el-button></el-form><div class="tip">管理员账号由首次启动后端时设置</div></el-card></div></template>
<style scoped>.login{min-height:100vh;display:grid;grid-template-columns:1.25fr .75fr;align-items:center;padding:8vw;background:radial-gradient(circle at 20% 20%,#447659,#183b2a 55%,#10271d);color:white}.brand{color:#e4bd77;letter-spacing:4px}.login h1{font-size:48px;line-height:1.25;margin:18px 0}.login p{color:#d4e3da;max-width:540px;line-height:1.8}.login-card{width:390px;justify-self:end;border:0;border-radius:18px;padding:12px;color:#263c2e}.role-picker{display:flex;width:100%}.role-picker :deep(.el-radio-button){flex:1}.role-picker :deep(.el-radio-button__inner){width:100%}.tip{margin-top:20px;padding:10px;background:#f4f7f4;color:#69766e;border-radius:8px;text-align:center;font-size:13px}@media(max-width:900px){.login{grid-template-columns:1fr}.login section{display:none}.login-card{justify-self:center;width:min(390px,90vw)}}</style>
